 * Shows entity navigation, JPQL autocomplete, and schema awareness.
 */
@Entity
@Table(
    name = "notification_template",
    uniqueConstraints = @UniqueConstraint(
        name = "uk_template_channel_code_locale",
        columnNames = {"channel", "template_code", "locale"}
    )
)
