package com.example.notifyhub.api;

import com.example.notifyhub.config.SecurityConfig;
import com.example.notifyhub.model.ServiceStatus;
import com.example.notifyhub.service.ChannelService;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.webmvc.test.autoconfigure.WebMvcTest;
import org.springframework.context.annotation.Import;
import org.springframework.http.MediaType;
import org.springframework.test.context.bean.override.mockito.MockitoBean;
import org.springframework.test.web.servlet.MockMvc;

import java.util.List;

import static org.mockito.BDDMockito.given;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.verifyNoInteractions;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.httpBasic;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.user;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.content;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@WebMvcTest(ChannelController.class)
@Import(SecurityConfig.class)
class ChannelControllerTest {

    @Autowired
    private MockMvc mockMvc;

    @MockitoBean
    private ChannelService channelService;

    @Test
    void getChannels_withoutCredentials_isUnauthorized() throws Exception {
        mockMvc.perform(get("/api/channels"))
                .andExpect(status().isUnauthorized());

        verifyNoInteractions(channelService);
    }

    @Test
    void getChannels_asNonAdmin_isForbidden() throws Exception {
        mockMvc.perform(get("/api/channels").with(user("bob").roles("USER")))
                .andExpect(status().isForbidden());

        verifyNoInteractions(channelService);
    }

    @Test
    void getChannels_asAdmin_returnsChannelServicesAsJson() throws Exception {
        given(channelService.getServices()).willReturn(List.of(
                new ServiceStatus("email", true),
                new ServiceStatus("sms", false)));

        mockMvc.perform(get("/api/channels").with(httpBasic("admin", "admin")))
                .andExpect(status().isOk())
                .andExpect(content().contentTypeCompatibleWith(MediaType.APPLICATION_JSON))
                .andExpect(jsonPath("$[0].channel").value("email"))
                .andExpect(jsonPath("$[0].enabled").value(true))
                .andExpect(jsonPath("$[1].channel").value("sms"))
                .andExpect(jsonPath("$[1].enabled").value(false));

        verify(channelService).getServices();
    }
}

package com.example.notifyhub.api;

import com.example.notifyhub.IntegrationTestBase;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.httpBasic;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.user;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

/**
 * Verifies that the notification API is locked down to the {@code ADMIN} role.
 */
@AutoConfigureMockMvc
class NotificationControllerSecurityTest extends IntegrationTestBase {

    @Autowired
    private MockMvc mockMvc;

    @Test
    void sendNotification_withoutCredentials_isUnauthorized() throws Exception {
        mockMvc.perform(post("/api/notify")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{}"))
                .andExpect(status().isUnauthorized());
    }

    @Test
    void sendNotification_asNonAdmin_isForbidden() throws Exception {
        mockMvc.perform(post("/api/notify")
                        .with(user("bob").roles("USER"))
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{}"))
                .andExpect(status().isForbidden());
    }

    @Test
    void sendNotification_asAdmin_passesAuthorization() throws Exception {
        // An empty body fails bean validation (400); reaching validation proves the
        // request cleared the security layer rather than being rejected as 401/403.
        mockMvc.perform(post("/api/notify")
                        .with(user("alice").roles("ADMIN"))
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{}"))
                .andExpect(status().isBadRequest());
    }

    @Test
    void sendNotification_withAdminBasicAuth_passesAuthorization() throws Exception {
        mockMvc.perform(post("/api/notify")
                        .with(httpBasic("admin", "admin"))
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{}"))
                .andExpect(status().isBadRequest());
    }

    @Test
    void health_isRestrictedToAdmin() throws Exception {
        mockMvc.perform(get("/api/health"))
                .andExpect(status().isUnauthorized());
    }
}

